mapper.select:
select trade_payment_amount, trade_desc, total_integral as totalIntegral, integral_goods as integralGoods
from ${database.prefix.payment}hou_pay_consume_trade
where order_id = #{orderId}
  and buyer_id = #{userId}

select order_state_id
from ${database.prefix.payment}hou_pay_consume_trade
where order_id = #{orderId}
  and buyer_id = #{userId}

mapper.update:
update ${database.prefix.payment}hou_pay_consume_trade
set order_state_id     = #{orderStateId},
    trade_pay_time     = #{paymentTime},
    trade_finish_time  = #{closeTime},
    payment_channel_id = #{paymentChannelId}
where order_id = #{outTradeNo}

update ${database.prefix.payment}hou_pay_consume_trade
set order_state_id     = #{orderStateId},
    trade_pay_time     = #{paymentTime},
    trade_finish_time  = #{closeTime},
    payment_channel_id = #{paymentChannelId}
where consume_trade_id = #{outTradeNo}
